rows=[]
for repo,n,decision,complexity,scope,work,deps,risks,test,reason in specs:
    row=dict(index[(repo,n)])
    row.update(decision=decision,complexity=complexity,source_scope=scope,work_screen=work,dependency_os_risks=deps,adapter_and_contract_risks=risks,test_plan=test,exclusion_or_gate=reason)
    rows.append(row)
save(ROOT/'candidates.json',rows)
with (ROOT/'candidates.csv').open('w',encoding='utf-8-sig',newline='') as out:
    fields=['repo','number','url','title','state','updated_at','repository_last_push','snapshot_head','decision','complexity','source_scope','work_screen','dependency_os_risks','adapter_and_contract_risks','test_plan','exclusion_or_gate']
    writer=csv.DictWriter(out,fieldnames=fields,extrasaction='ignore');writer.writeheader();writer.writerows(rows)
lines=['# Live GitHub issue screening','',f"Captured {json.loads((ROOT/'provenance.json').read_text())['collected_at_utc']}. 36 issue threads screened, 61 directly linked PRs fetched; 14 detailed candidate rows. All issue records were open at capture, but open is not equivalent to unresolved.",'','No qualifying two-pilot or 3–5-task cohort was found under all current requirements. Do not silently lower the active-work, source-scope, or independent-verification gates. No reproductions were executed.','','## Ranked reserves, not approved pilots','','1. [async-mutex #90](https://github.com/DirtyHairy/async-mutex/issues/90) is the strongest meaningful stateful fallback. Current source independently confirms both O(capacity) scans. No observed linked/claimed implementation. src/ edits fit, but the repo has not pushed since July 2025 and Node24 strip-types cannot load its parameter properties/extensionless imports unmodified. Source-driven loading and a bounded correctness/performance oracle must be demonstrated before freeze. This is conditional, not ready.','2. [Vitest #11585](https://github.com/vitest-dev/vitest/issues/11585) is the strongest genuinely untreated integration reserve: linked package optimizer metadata, dependency graph, related/changed selection, and watch state. No observed fix in timeline or 19 current open PRs, and author explicitly has not tried a patch. The frozen engine excludes its packages/vitest/src layout and real CLI/subprocess verification. It cannot be made eligible by relocating source or substituting a toy graph test.','','A defensible 3–5 task cohort cannot be recommended from this screen. These two reserves are conditional in different ways; all other detailed candidates are excluded. Arquero #329 is also untreated but stale and under-reproduced. No clean third candidate emerged.','','## Detailed 14-candidate screen','','| Issue | Decision | Reason |','|---|---|---|']
for r in rows: lines.append(f"| [{r['repo']} #{r['number']}]({r['url']}) | {r['decision']} | {r['exclusion_or_gate']} |")
lines += ['','Full per-candidate acceptance plans, complexity, dependency/OS risks, source-scope risks, head SHAs, and source provenance are in candidates.json / candidates.csv.','','## Wider screening appendix','','Every additional raw thread is retained. Reject rationale: linked implementation, claimed local implementation, no current repro/active maintainer evidence, unsupported/unclear requested behavior, or current adapter incompatibility. The exact raw body/comments/timeline are authoritative; absence of a link alone is never treated as proof of availability.','','| Issue | Screening evidence |','|---|---|']
primary={(r['repo'],r['number']) for r in rows}
manual={('DirtyHairy/async-mutex',88):'The acquire in Promise.all obtains the lock and never releases it until waitForUnlock finishes; likely expected locking semantics, not established bug.',('NaturalIntelligence/fast-xml-parser',689):'Maintainer says demo-only; reporter confirms library works. Not a src library bug.',('NaturalIntelligence/fast-xml-parser',708):'Comment reports missing #text fixed in commit31bbc99/v5.7.3; remaining option request has incompatible expectations.',('NaturalIntelligence/fast-xml-parser',888):'Maintainer says underlying strnum bug fixed/released; old v4-specific backport not validated.'}
for r in allrows:
    if (r['repo'],r['number']) in primary: continue
    prs=r['linked_prs']; opened=[p for p in prs if p['state']=='open']; merged=[p for p in prs if p['merged_at']]
    why=manual.get((r['repo'],r['number'])) or ('Open linked work: '+', '.join(p['url'].split('/pull/')[1] for p in opened) if opened else 'Prior merged/closed work or contract/adapter needs further investigation; not recommended.')
    lines.append(f"| [{r['repo']} #{r['number']}]({r['url']}) | {why} |")
lines += ['','## Provenance and limitations','','snapshots/<owner>__<repo>/<issue>/issue.json contains original issue body and status; comments.json contains complete paginated comment pages; timeline.json contains timeline pages. Repository metadata, default-branch head commit, root listing, package.json, and open-prs.json are alongside. linked-pr-status.json contains directly re-fetched PR state/merge status; individual raw PR payloads are under linked-pr-details. all-screened-live-status.json indexes every thread.','','Undici open-pr listing reached its100 cap; all cited directly linked fixes were individually refreshed, so exclusions are sound but no absence-of-work claim should be inferred for that repo. Other observed open PR lists were below100. Repository timestamps can include bot activity. GitHub statuses can change after capture; refresh selection immediately before any future freeze. Read-only gh API work only. No public comments/PRs, implementation, harness edits, clones, dependency installs, or reproduction execution.']
(ROOT/'SCREENING.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
manifest=[]
for p in sorted(ROOT.rglob('*')):
    if p.is_file() and p.name!='sha256-manifest.json' and '__pycache__' not in str(p): manifest.append({'file':str(p.relative_to(ROOT)).replace('\\','/'),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
save(ROOT/'sha256-manifest.json',manifest)
print(f'Wrote {len(rows)} structured candidates and screening report; {len(manifest)} artifacts hashed.')
